import {runLinkageEvaluation} from './linkage-lab-core.mjs';
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let report=null;
const pct=value=>value===null?'Not measured':`${(value*100).toFixed(1)}%`;
const firstLabel=row=>row.ranking.length?row.candidates.find(c=>c.id===row.ranking[0].id).label:'No result';
const badge=label=>`<span class="lab-label ${label.toLowerCase()}">${esc(label)}</span>`;
function render(){
 if(!report){$('lab-results').innerHTML='<p class="lab-empty">Run comparison to see first-result errors, missed related reports and every original passage.</p>';return;}
 const [base,challenger]=report.results;
 const rows=base.rows.map((row,i)=>({row,other:challenger.rows[i]})).filter(({row,other})=>{switch($('lab-filter').value){case 'false-first':return [row,other].some(r=>firstLabel(r)==='Unrelated');case 'missed':return [row,other].some(r=>r.candidates.some(c=>c.label==='Related'&&!r.ranking.slice(0,3).some(s=>s.id===c.id)));case 'different':return row.ranking.map(r=>r.id).join('|')!==other.ranking.map(r=>r.id).join('|');default:return true;}});
 $('lab-results').innerHTML=`<p class="lab-partition"><strong>${esc(report.split==='evaluation'?'Evaluation partition':'Development partition')}</strong> · ${base.metrics.queries} authored queries · Suite ${esc(report.suiteVersion)}</p><div class="lab-summary">${report.results.map(m=>`<article class="lab-score"><h2>${esc(m.name)}</h2><strong class="score-value">${m.metrics.correctTop1} / ${m.metrics.queries}</strong><span class="score-label">related reports ranked first</span><div class="lab-metrics"><div><strong>${m.metrics.falseTop1}</strong><span>unrelated first results</span></div><div><strong>${pct(m.metrics.recallAt3)}</strong><span>mean recall within top 3</span></div><div><strong>${m.metrics.mrr.toFixed(3)}</strong><span>mean reciprocal rank</span></div><div><strong>${m.metrics.unrelatedTop3}</strong><span>unrelated reports in top 3</span></div></div><p class="muted">${m.metrics.unresolvedTop1} unresolved first results · ${m.metrics.noResults} empty results · ${m.metrics.unresolvedTop3} unresolved reports in top 3.</p></article>`).join('')}</div><div class="lab-decision"><strong>No automatic method change.</strong><p>${challenger.metrics.correctTop1>base.metrics.correctTop1?'BM25 ranks a related report first more often in this small partition. Check its missed reports, extra unrelated results and the other partition before drawing a conclusion.':'BM25 does not improve first-result success in this partition. A search-ranking change alone has not resolved the event-linking problem.'} These authored results do not measure real threat detection or prevention.</p></div><h2>Inspect the evidence behind the scores</h2><p class="muted">Showing ${rows.length} of ${base.rows.length} examples. Summary scores always include the whole selected partition.</p>${rows.length?rows.map(({row,other})=>`<article class="panel lab-query"><div class="lab-query-heading"><div><h3>${esc(row.category)}</h3><small>${esc(row.id)} · known by ${esc(row.asOf)} · ${row.excluded} future candidates excluded</small></div><span class="chip">FICTIONAL</span></div><p class="query-text">${esc(row.query.text)}</p><div class="lab-first">${[{name:base.name,data:row},{name:challenger.name,data:other}].map(m=>`<div>${esc(m.name)}<strong>${m.data.ranking.length?esc(m.data.ranking[0].id):'No qualifying report'}</strong>${badge(firstLabel(m.data))}</div>`).join('')}</div><details><summary>Inspect all ${row.candidates.length} original candidates and authored labels</summary>${row.candidates.map(c=>`<div class="lab-candidate"><div class="lab-candidate-head"><strong>${esc(c.id)}</strong>${badge(c.label)}</div><p>${esc(c.text)}</p><p class="muted">Authored rationale: ${esc(c.reason)}</p><p class="muted">${[{name:base.name,data:row},{name:challenger.name,data:other}].map(m=>{const rank=m.data.ranking.findIndex(r=>r.id===c.id);return `${esc(m.name)}: ${rank<0?'not retrieved':`rank ${rank+1} · score ${m.data.ranking[rank].score.toFixed(3)}`}`;}).join(' | ')}</p></div>`).join('')}</details></article>`).join(''):'<p class="lab-empty">No examples match this inspection filter. The full-partition scores above are unchanged.</p>'}`;
}
$('lab-form').addEventListener('submit',event=>{event.preventDefault();try{report=runLinkageEvaluation($('lab-split').value);$('lab-error').textContent='';$('lab-status').textContent=`Completed ${report.split} comparison locally. No reports or workspace records changed.`;render();}catch(error){report=null;render();$('lab-error').textContent=error.message;}});
$('lab-split').addEventListener('change',()=>{report=null;render();$('lab-status').textContent='Partition changed. Run comparison to calculate its results.';$('lab-error').textContent='';});
$('lab-filter').addEventListener('change',render);render();
